source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            if y1-y0 >= 2 and x1-x0 >= 2 and len(cells) == 2*(y1-y0)+2*(x1-x0):
                if all(grid[y0][x] == color and grid[y1][x] == color for x in range(x0,x1+1)) and all(grid[y][x0] == color and grid[y][x1] == color for y in range(y0,y1+1)):
                    boxes.append((x0, y0, x1, y1, color))
    frame_colors = {b[4] for b in boxes}
    counts = {}
    for row in grid:
        for color in row:
            if color != 0 and color not in frame_colors:
                counts[color] = counts.get(color, 0) + 1
    marker_colors = sorted(counts, key=lambda color: (counts[color], color))[:len(boxes)]
    boxes.sort(key=lambda b: b[0])
    result = [[0]*w for _ in range(h)]
    for x0,y0,x1,y1,color in boxes:
        for y in range(y0,y1+1):
            for x in range(x0,x1+1):
                if y in (y0,y1) or x in (x0,x1):
                    result[y][x] = color
    for (x0,y0,x1,y1,color), fill in zip(boxes, marker_colors):
        for y in range(y0+1,y1):
            for x in range(x0+1,x1):
                if (y-y0-1 + x-x0-1) % 2 == 0:
                    result[y][x] = fill
    return result
